DO $verify$
DECLARE
  n int;
BEGIN
  SELECT COUNT(*)::int INTO n FROM public.junior_vocab WHERE word_id IS NOT NULL;
  IF n <> 2373 THEN
    RAISE EXCEPTION 'junior_vocab PEP ingest row count mismatch: expected 2373, got %', n;
  END IF;
END $verify$;

VALUES (1, 2373, now())
